// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    Recorder rec;

    function setUp() public {
        c = new MyContract();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < 1e18);
        vm.deal(address(c), amount);

        bool ok;
        try c.sendTo(address(rec), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: when sendTo succeeds, its receiver was invoked via
        // `transfer`, i.e. it was handed only the 2300-gas stipend. A callee
        // that accepts funds can therefore never observe more than a tiny
        // gas allowance at entry. The mutant's `call{value:...}` forwards
        // all remaining gas, so the recorder observes a large allowance.
        assertTrue(!ok || rec.gasAtEntry() < 10000);
    }
}

contract Recorder {
    uint256 public gasAtEntry;

    receive() external payable {
        gasAtEntry = gasleft();
    }
}
